// from a list of checkpoint IDs. It first tries the pre-built info map (which has
// CreatedAt from ListCheckpoints), then falls back to reading metadata from the tree
// for more accurate timestamps. If only one ID is provided, it returns it directly.
func resolveLatestCheckpointFromMap(cpIDs []id.CheckpointID, infoMap map[id.CheckpointID]CheckpointInfo, metadataTree *object.Tree) (id.CheckpointID, CheckpointInfo, bool) {
	// Filter to IDs that have metadata
	var validIDs []id.CheckpointID
	for _, cpID := range cpIDs {
		if _, ok := infoMap[cpID]; ok {
			validIDs = append(validIDs, cpID)
		}
	}
	if len(validIDs) == 0 {
		return id.EmptyCheckpointID, CheckpointInfo{}, false
	}
	if len(validIDs) == 1 {
		info := infoMap[validIDs[0]]
		return validIDs[0], info, true
	}

	// Multiple checkpoints: resolve by CreatedAt from metadata tree (most accurate),
	// falling back to the info map's CreatedAt.
	type cpWithTime struct {
		id        id.CheckpointID
		info      CheckpointInfo
		createdAt time.Time
	}
	candidates := make([]cpWithTime, 0, len(validIDs))
	for _, cpID := range validIDs {
		info := infoMap[cpID]
		createdAt := info.CreatedAt
		// Try reading from the metadata tree for a more accurate timestamp
		if metadataTree != nil {
			if metadata, err := ReadCheckpointMetadata(metadataTree, cpID.Path()); err == nil {
				createdAt = metadata.CreatedAt
			}
		}
		candidates = append(candidates, cpWithTime{id: cpID, info: info, createdAt: createdAt})
	}

	// Sort by CreatedAt ascending — last element is the newest
	sort.Slice(candidates, func(i, j int) bool {
		return candidates[i].createdAt.Before(candidates[j].createdAt)
	})

	latest := candidates[len(candidates)-1]
	return latest.id, latest.info, true
}

